                            __FUNCTION__);
        return;
    case 0x50:	
        s->autoidle &= ~3;
        s->autoidle |= value & 3;
        return;

    case 0x84:	
        bank->mask = value;
        omap_inth_update(s, 0);
        omap_inth_update(s, 1);
        return;
    case 0x88:	
        bank->mask &= ~value;
        omap_inth_update(s, 0);
        omap_inth_update(s, 1);
        return;
    case 0x8c:	
        bank->mask |= value;
        return;
    case 0x90:	
        bank->irqs |= bank->swi |= value;
        omap_inth_update(s, 0);
        omap_inth_update(s, 1);
        return;
    case 0x94:	
        bank->swi &= ~value;
        bank->irqs = bank->swi & bank->inputs;
        return;

