// Function to pad data to AES block size
unsigned char* pad_data(const unsigned char* data, size_t data_len, size_t* padded_len) {
    size_t padding = DES_BLOCK_SIZE - (data_len % DES_BLOCK_SIZE);
    *padded_len = data_len + padding;

