        free(result.iv);
        free(result.key);
        free(padded_data);
        return result;
    }

    // Perform CBC mode encryption
    unsigned char iv_copy[AES_BLOCK_SIZE];
    memcpy(iv_copy, result.iv, AES_BLOCK_SIZE);
